            /* EGYSÉGESÍTVE A KÉK GRADIENSRE */
            --accent-research-gradient: var(--user-bubble-bg);
            --safe-top: env(safe-area-inset-top);
            --safe-bottom: env(safe-area-inset-bottom);
        }

        * {
            box-sizing: border-box;
            margin: 0;
            padding: 0;
        }

        html {
            scroll-behavior: smooth;
        }

        body {
            font-family: "SF Pro Display", "SF Pro Text", -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, Helvetica, Arial, sans-serif;
            background: linear-gradient(180deg,
                    var(--bg-color) 0%,
                    #0a0a0a 50%,
                    var(--bg-color) 100%);
            color: var(--text-primary);
            height: 100dvh;
            width: 100vw;
            display: flex;
            flex-direction: column;
            overflow: hidden;
        }

        #canvas-bg {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            z-index: -1;
            opacity: 0.15;
        }

        /* --- 1. NÉZET: CHAT FELÜLET --- */
        #chat-view {
            display: flex;
            flex-direction: column;
            width: 100%;
            height: 100%;
            background: transparent;
            transition: transform 0.5s cubic-bezier(0.25, 1, 0.5, 1),
                filter 0.5s cubic-bezier(0.25, 1, 0.5, 1),
                border-radius 0.5s cubic-bezier(0.25, 1, 0.5, 1);
        }

        #chat-view.research-active {
            transform: scale(0.95);
            filter: brightness(0.7);
            border-radius: 20px;
            overflow: hidden;
            pointer-events: none;
        }

        .frosted-header {
            position: sticky;
            top: 0;
            width: 100%;
            background: var(--header-footer-bg);
            backdrop-filter: blur(20px) saturate(180%);
            -webkit-backdrop-filter: blur(20px) saturate(180%);
            z-index: 10;
            padding: 12px 20px;
            padding-top: calc(12px + var(--safe-top));
            border-bottom: 1px solid var(--widget-border);
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .frosted-header h1 {
            font-size: 1rem;
            font-weight: 600;
        }

        #chat-history {
            flex-grow: 1;
            overflow-y: auto;
            -webkit-overflow-scrolling: touch;
            padding: 1.5rem 1rem;
            display: flex;
            flex-direction: column;
            gap: 1.25rem;
            scroll-behavior: smooth;
        }

        @keyframes message-pop-in {
            from {
                opacity: 0;
                transform: scale(0.95);
            }

            to {
                opacity: 1;
                transform: scale(1.0);
            }
        }

        .message {
            max-width: 80%;
            padding: 12px 18px;
            border-radius: 20px;
            line-height: 1.5;
            font-size: 0.95rem;
            word-wrap: break-word;
            box-shadow: 0 4px 10px rgba(0, 0, 0, 0.2);
            font-weight: 400;
        }

        .message:not(.widget) {
            animation: message-pop-in 0.3s cubic-bezier(0.25, 1, 0.5, 1);
        }

        .message.user {
            background: var(--user-bubble-bg);
            color: #fff;
            align-self: flex-end;
            border-bottom-right-radius: 8px;
        }

        .message.ai {
            background: var(--ai-bubble-bg);
            color: var(--text-primary);
            align-self: flex-start;
            border-bottom-left-radius: 8px;
            border: 1px solid var(--widget-border);
        }

        .message.ai.error {
            background-image: linear-gradient(135deg, #552525, #442222);
            border: 1px solid #883333;
            color: #FFDDDD;
        }

        .message.ai.typing-indicator {
            background: var(--ai-bubble-bg);
            padding: 12px 18px;
            align-self: flex-start;
            border: 1px solid var(--widget-border);
        }

        .typing-dot {
            display: inline-block;
            width: 8px;
            height: 8px;
            border-radius: 50%;
            background: var(--text-secondary);
            animation: typing-ios 1.4s infinite;
        }

        .typing-dot:nth-child(2) {
            animation-delay: 0.2s;
        }

        .typing-dot:nth-child(3) {
            animation-delay: 0.4s;
        }

        @keyframes typing-ios {

            0%,
            60%,
            100% {
                transform: scale(0.4);
                opacity: 0.5;
            }

            30% {
                transform: scale(1.0);
                opacity: 1;
            }
        }

        .message.widget {
            max-width: 90%;
            align-self: center;
            width: 100%;
            background: var(--widget-bg);
            backdrop-filter: blur(15px) saturate(180%);
            -webkit-backdrop-filter: blur(15px) saturate(180%);
            border: 1px solid var(--widget-border);
            border-radius: 14px;
            padding: 16px;
            cursor: pointer;
            transition: transform 0.2s ease, box-shadow 0.2s ease;
        }

        .widget-header {
            display: flex;
            align-items: center;
            gap: 10px;
            margin-bottom: 12px;
        }

        .widget-header svg {
            width: 24px;
            height: 24px;
            color: var(--accent-blue);
            /* SZÍN CSERÉLVE */
            flex-shrink: 0;
        }

        .widget-header h3 {
            font-size: 1rem;
            font-weight: 600;
        }

        .widget-body .task-goal {
            font-size: 0.85rem;
            color: var(--text-secondary);
            margin-bottom: 12px;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .widget-body .task-params-summary {
            font-size: 0.75rem;
            color: var(--accent-blue);
            /* SZÍN CSERÉLVE */
            margin-bottom: 12px;
            font-style: italic;
        }

        .widget-status {
            font-size: 0.8rem;
            color: var(--text-primary);
            margin-bottom: 5px;
        }

        .widget-progress-bar {
            width: 100%;
            height: 5px;
            background: rgba(255, 255, 255, 0.1);
            border-radius: 2.5px;
            overflow: hidden;
        }

        .widget-progress-inner {
            width: 0%;
            height: 100%;
            background: var(--accent-research-gradient);
            /* SZÍN CSERÉLVE */
            transition: width 0.5s ease-out;
        }

        /* Alsó beviteli sáv */
        footer {
            position: sticky;
            bottom: 0;
            width: 100%;
            background: var(--header-footer-bg);
            backdrop-filter: blur(20px) saturate(180%);
            -webkit-backdrop-filter: blur(20px) saturate(180%);
            border-top: 1px solid var(--widget-border);
            z-index: 10;
            padding: 10px 15px;
            padding-bottom: calc(10px + var(--safe-bottom));
            position: relative;
        }

        #message-form {
            display: flex;
            align-items: center;
            gap: 10px;
        }

        #add-button {
            background: var(--input-bg);
            border: 1px solid var(--widget-border);
            border-radius: 50%;
            width: 36px;
            height: 36px;
            display: flex;
            align-items: center;
            justify-content: center;
            flex-shrink: 0;
            cursor: pointer;
            transition: all 0.3s ease;
            color: var(--accent-blue);
        }

        #add-button:hover {
            border-color: var(--accent-blue);
        }

        #add-button svg {
            width: 20px;
            height: 20px;
        }

        #action-popup-menu {
            position: absolute;
            bottom: calc(100% - 10px);
            left: 15px;
            width: 250px;
            background: var(--header-footer-bg);
            backdrop-filter: blur(20px) saturate(180%);
            -webkit-backdrop-filter: blur(20px) saturate(180%);
            border: 1px solid var(--widget-border);
            border-radius: 14px;
            padding: 8px;
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
            z-index: 1000;
            opacity: 0;
            transform: translateY(10px);
            transition: opacity 0.3s ease, transform 0.3s ease;
            pointer-events: none;
        }

        #action-popup-menu.visible {
            opacity: 1;
            transform: translateY(0);
            pointer-events: auto;
        }

        .popup-menu-item {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 12px;
            background: none;
            border: none;
            color: var(--text-primary);
            font-size: 0.9rem;
            font-weight: 500;
            border-radius: 8px;
            width: 100%;
            text-align: left;
            cursor: pointer;
        }

        .popup-menu-item:hover {
            background: rgba(255, 255, 255, 0.1);
        }

        .popup-menu-item svg {
            width: 20px;
            height: 20px;
            flex-shrink: 0;
        }

        #menu-research svg {
            color: var(--accent-blue);
            /* SZÍN CSERÉLVE */
        }

        #menu-upload svg {
            color: var(--accent-blue);
        }

        #message-input {
            flex-grow: 1;
            background-color: var(--input-bg);
            border: 1px solid var(--widget-border);
            border-radius: 20px;
            padding: 10px 18px;
            color: #fff;
            font-size: 16px;
            font-family: inherit;
            outline: none;
            transition: border-color 0.3s ease;
        }

        #message-input.mode-research {
            border-color: var(--accent-blue);
            /* SZÍN CSERÉLVE */
        }

        #message-input:focus {
            border-color: var(--accent-blue);
        }

        #message-input.mode-research:focus {
            border-color: var(--accent-blue);
            /* SZÍN CSERÉLVE */
        }

        #send-button {
            border: none;
            border-radius: 50%;
            width: 36px;
            height: 36px;
            color: white;
            display: flex;
            align-items: center;
            justify-content: center;
            cursor: pointer;
            transition: all 0.3s ease;
            flex-shrink: 0;
        }

        #send-button svg {
            width: 20px;
            height: 20px;
            transition: transform 0.3s ease;
        }

        #send-button.mode-chat {
            background: var(--user-bubble-bg);
        }

        #send-button.mode-chat svg {
            transform: rotate(90deg);
            margin-left: 0;
            margin-top: -1px;
        }

        #send-button.mode-research {
            background: var(--accent-research-gradient);
            /* SZÍN CSERÉLVE */
        }

        #send-button.mode-research svg {
            transform: rotate(0deg);
            margin-left: 0;
            margin-top: 0;
        }

        #send-button:disabled {
            background: #555 !important;
            cursor: not-allowed;
        }

        #icon-send,
        #icon-research {
            display: none;
        }

        #send-button.mode-chat #icon-send {
            display: block;
        }

        #send-button.mode-research #icon-research {
            display: block;
        }

        /* --- 2. NÉZET: PRÉMIUM KUTATÁSI NÉZET --- */
        #research-view {
            display: flex;
            flex-direction: column;
            width: 100%;
            height: 100dvh;
            position: fixed;
            top: 0;
            left: 0;
            z-index: 100;
            /* FRISSÍTÉS: A háttér áttetsző, hogy a 3D canvas látszódjon */
            background: transparent;
            transform: translateX(100%);
            transition: transform 0.5s cubic-bezier(0.25, 1, 0.5, 1);
        }

        #research-view.visible {
            transform: translateX(0);
        }

        #research-header {
            padding-left: 10px;
            padding-right: 20px;
            justify-content: space-between;
            flex-shrink: 0;
        }

        #research-back-button {
            background: none;
            border: none;
            color: var(--accent-blue);
            font-size: 1rem;
            font-weight: 500;
            cursor: pointer;
            display: flex;
            align-items: center;
            gap: 4px;
            padding: 5px;
        }

        #research-back-button svg {
            width: 24px;
            height: 24px;
        }

        #research-title {
            font-size: 1rem;
            font-weight: 600;
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
            max-width: 60%;
        }

        #research-content {
            flex-grow: 1;
            overflow-y: auto;
            padding: 24px;
            display: flex;
            flex-direction: column;
            gap: 24px;
        }

        .research-section-title {
            font-size: 1.1rem;
            font-weight: 600;
            color: var(--accent-blue);
            padding-bottom: 8px;
            border-bottom: 1px solid var(--widget-border);
            margin-bottom: -8px;
        }

        .agent-grid {
            display: grid;
            grid-template-columns: 1fr 1fr;
            gap: 16px;
        }

        .agent-card {
            background: var(--ai-bubble-bg);
            border: 1px solid var(--widget-border);
            border-radius: 20px;
            padding: 20px;
            display: flex;
            align-items: center;
            gap: 16px;
        }

        .agent-progress-donut {
            flex-shrink: 0;
        }

        .agent-progress-donut .donut-fg {
            transition: stroke-dashoffset 0.5s ease-out;
            transform-origin: 50% 50%;
        }

        .agent-progress-donut .donut-text {
            font-size: 12px;
            font-weight: 600;
            fill: var(--text-primary);
        }

        .agent-card-info .agent-card-title {
            font-size: 0.9rem;
            font-weight: 600;
        }

        .agent-card-info .agent-card-status {
            font-size: 0.8rem;
            color: var(--text-secondary);
        }

        .similar-link-item,
        .webset-item {
            display: flex;
            align-items: center;
            gap: 12px;
            padding: 16px;
            background: var(--ai-bubble-bg);
            border: 1px solid var(--widget-border);
            border-radius: 12px;
        }

        .icon-placeholder {
            width: 36px;
            height: 36px;
            flex-shrink: 0;
            background: var(--input-bg);
            border-radius: 8px;
            display: flex;
            align-items: center;
            justify-content: center;
        }

        .icon-placeholder svg {
            width: 20px;
            height: 20px;
            color: var(--text-secondary);
        }

        .item-text .item-title {
            font-size: 0.9rem;
            font-weight: 500;
            color: var(--text-primary);
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        .item-text .item-url {
            font-size: 0.8rem;
            color: var(--text-secondary);
            white-space: nowrap;
            overflow: hidden;
            text-overflow: ellipsis;
        }

        /* --- 3. KUTATÁSI OPCIÓK: MODÁL -> BOTTOM SHEET --- */
        #research-options-modal-overlay {
            position: fixed;
            top: 0;
            left: 0;
            width: 100%;
            height: 100%;
            background: rgba(0, 0, 0, 0.5);
            backdrop-filter: blur(20px) saturate(180%);
            -webkit-backdrop-filter: blur(20px) saturate(180%);
            z-index: 99;
            /* FRISSÍTÉS: Alulra igazítva a sheet-hez */
            display: flex;
            align-items: flex-end;
            justify-content: center;
            opacity: 0;
            transition: opacity 0.4s cubic-bezier(0.25, 1, 0.5, 1);
            pointer-events: none;
        }

        #research-options-modal-overlay.visible {
            opacity: 1;
            pointer-events: auto;
        }

        /* FRISSÍTÉS: Átstilizálva Bottom Sheet-té */
        #research-options-modal {
            background: var(--header-footer-bg);
            border-radius: 20px 20px 0 0;
            /* Lekerekítés csak felül */
            border: 1px solid var(--widget-border);
            border-bottom: none;
            width: 100%;
            max-width: 100%;
            /* Törölve a régi max-width */
            padding: 20px;
            padding-top: 10px;
            /* Hely a handle-nek */
            padding-bottom: calc(20px + var(--safe-bottom));
            /* Biztonsági sáv */
            box-shadow: 0 10px 30px rgba(0, 0, 0, 0.3);
            /* ÚJ: Animáció alulról */
            transform: translateY(100%);
            transition: transform 0.4s cubic-bezier(0.25, 1, 0.5, 1);
        }

        #research-options-modal-overlay.visible #research-options-modal {
            transform: translateY(0);
        }

        /* ÚJ: "Handle" (fogantyú) a sheet tetején */
        .modal-handle {
            width: 40px;
            height: 5px;
            background: var(--widget-border);
            border-radius: 2.5px;
            margin: 0 auto 15px;
        }


        #research-options-modal h2 {
            font-size: 1.1rem;
            font-weight: 600;
            text-align: center;
            margin-bottom: 10px;
        }

        #research-goal-summary {
            font-size: 0.9rem;
            text-align: center;
            color: var(--text-secondary);
            margin-bottom: 20px;
            padding: 10px;
            background: var(--input-bg);
            border-radius: 8px;
        }

        #toggle-advanced-options {
            background: none;
            border: none;
            color: var(--accent-blue);
            font-size: 0.85rem;
            cursor: pointer;
            margin-bottom: 15px;
        }

        #advanced-options-container {
            border-top: 1px solid var(--widget-border);
            padding-top: 15px;
            margin-bottom: 15px;
            display: none;
        }

        .form-group {
            margin-bottom: 10px;
        }

        .form-group label {
            display: block;
            font-size: 0.75rem;
            color: var(--text-secondary);
            margin-bottom: 5px;
            font-weight: 500;
        }

        .form-group input {
            width: 100%;
            background-color: var(--input-bg);
            border: 1px solid var(--widget-border);
            border-radius: 8px;
            padding: 8px 12px;
            color: #fff;
            font-size: 0.9rem;
            font-family: inherit;
        }

        .form-group input[type="date"] {
            color-scheme: dark;
            -webkit-appearance: none;
        }

        #submit-research-task {
            width: 100%;
            background: var(--accent-research-gradient);
            /* SZÍN CSERÉLVE */
            color: white;
            border: none;
            border-radius: 10px;
            padding: 12px;
            font-size: 1rem;
            font-weight: 600;
            cursor: pointer;
        }

        #cancel-research-task {
            width: 100%;
            background: none;
            color: var(--text-secondary);
            border: none;
            padding: 10px;
            font-size: 0.9rem;
            cursor: pointer;
            text-align: center;
            margin-top: 10px;
        }
    </style>
</head>

<body>

    <canvas id="canvas-bg"></canvas>

    <!-- ============================================= -->
    <!-- ========= 1. NÉZET: CHAT FELÜLET =========== -->
    <!-- ============================================= -->
    <div id="chat-view">
        <header class="frosted-header">
            <h1>Cerebras Asszisztens</h1>
        </header>

        <main id="chat-history">
            <!-- Üzenetek és widgetek ide kerülnek -->
        </main>

        <footer>
