                <button class="popup-menu-item" id="menu-research">
                    <svg xmlns="" viewBox="0 0 20 20" fill="currentColor">
                        <path fill-rule="evenodd"
                            d="M11.29 2.234a.75.75 0 0 0-1.071 1.071 7.5 7.5 0 0 1 2.39 7.195.75.75 0 1 0 1.488-.287 9 9 0 0 0-2.86-8.622.75.75 0 0 0-.947-.357Z"
                            clip-rule="evenodd" />
                        <path fill-rule="evenodd"
                            d="M8.71 2.234a.75.75 0 0 1 .947-.357 9 9 0 0 1 2.86 8.622.75.75 0 1 1-1.488-.287 7.5 7.5 0 0 0-2.39-7.195.75.75 0 0 1-.929-1.071l.001-.001.001-.001Z"
