                        <path fill-rule="evenodd"
                            d="M10 18.25a8.25 8.25 0 1 0 0-16.5 8.25 8.25 0 0 0 0 16.5ZM10 3.25a6.75 6.75 0 1 0 0 13.5 6.75 6.75 0 0 0 0-13.5Z"
                            clip-rule="evenodd" />
                    </svg>
                    Mély Kutatás
                </button>
                <button class="popup-menu-item" id="menu-upload">
                    <svg xmlns="" viewBox="0 0 20 20" fill="currentColor">
                        <path fill-rule="evenodd"
                            d="M15.621 4.379a3 3 0 0 0-4.242 0l-7 7a3 3 0 0 0 4.241 4.243L15.75 8.25a.75.75 0 0 1 1.06 1.06l-7.12 7.123a4.5 4.5 0 0 1-6.364-6.364l7-7a4.5 4.5 0 0 1 6.364 6.364l-1.06 1.06a.75.75 0 0 1-1.06-1.06l1.06-1.06a3 3 0 0 0-4.243-4.242l-7 7a3 3 0 0 0 0 4.242 3 3 0 0 0 4.242 0l7.12-7.123a.75.75 0 0 1 1.06-1.06l-1.06-1.06Z"
