                    </svg>
                    Fájl Feltöltés
                </button>
            </div>

            <form id="message-form">
                <button type="button" id="add-button">
                    <svg xmlns="" viewBox="0 0 20 20" fill="currentColor">
                        <path
                            d="M10.75 4.75a.75.75 0 0 0-1.5 0v4.5h-4.5a.75.75 0 0 0 0 1.5h4.5v4.5a.75.75 0 0 0 1.5 0v-4.5h4.5a.75.75 0 0 0 0-1.5h-4.5v-4.5Z" />
                    </svg>
                </button>

                <input type="text" id="message-input" class="mode-chat" placeholder="Üzenet..." autocomplete="off">

                <button type="submit" id="send-button" class="mode-chat" disabled>
                    <svg id="icon-send" xmlns="" viewBox="0 0 20 20" fill="currentColor">
                        <path
                            d="M3.105 3.105a.75.75 0 0 1 1.06 0L10 8.94l5.835-5.835a.75.75 0 1 1 1.06 1.06L11.06 10l5.835 5.835a.75.75 0 1 1-1.06 1.06L10 11.06l-5.835 5.835a.75.75 0 1 1-1.06-1.06L8.94 10 3.105 4.165a.75.75 0 0 1 0-1.06Z"
                            transform="rotate(90 10 10)" />
                    </svg>
                    <svg id="icon-research" xmlns="" viewBox="0 0 20 20" fill="currentColor">
                        <path fill-rule="evenodd"
                            d="M11.29 2.234a.75.75 0 0 0-1.071 1.071 7.5 7.5 0 0 1 2.39 7.195.75.75 0 1 0 1.488-.287 9 9 0 0 0-2.86-8.622.75.75 0 0 0-.947-.357Z"
                            clip-rule="evenodd" />
                        <path fill-rule="evenodd"
                            d="M8.71 2.234a.75.75 0 0 1 .947-.357 9 9 0 0 1 2.86 8.622.75.75 0 1 1-1.488-.287 7.5 7.5 0 0 0-2.39-7.195.75.75 0 0 1-.929-1.071l.001-.001.001-.001Z"
