                        <path fill-rule="evenodd"
                            d="M10 18.25a8.25 8.25 0 1 0 0-16.5 8.25 8.25 0 0 0 0 16.5ZM10 3.25a6.75 6.75 0 1 0 0 13.5 6.75 6.75 0 0 0 0-13.5Z"
                            clip-rule="evenodd" />
                    </svg>
                </button>
            </form>
        </footer>
    </div>

