    <script type="module">
        let scene, camera, renderer, mesh, uniforms;
        const clock = new THREE.Clock();
        function init3DBackground() {
            scene = new THREE.Scene();
            camera = new THREE.PerspectiveCamera(75, window.innerWidth / window.innerHeight, 0.1, 1000);
            renderer = new THREE.WebGLRenderer({canvas: document.getElementById('canvas-bg'), alpha: true});
            renderer.setSize(window.innerWidth, window.innerHeight);
            renderer.setPixelRatio(window.devicePixelRatio);
            const geometry = new THREE.PlaneGeometry(20, 20, 100, 100);
            const vertexShader = `varying vec2 vUv;uniform float u_time;vec3 mod289(vec3 x){return x-floor(x*(1.0/289.0))*289.0;}vec2 mod289(vec2 x){return x-floor(x*(1.0/289.0))*289.0;}vec3 permute(vec3 x){return mod289(((x*34.0)+1.0)*x);}float snoise(vec2 v){const vec4 C=vec4(0.211324865405187,0.366025403784439,-0.577350269189626,0.024390243902439);vec2 i=floor(v+dot(v,C.yy));vec2 x0=v-i+dot(i,C.xx);vec2 i1;i1=(x0.x>x0.y)?vec2(1.0,0.0):vec2(0.0,1.0);vec4 x12=x0.xyxy+C.xxzz;x12.xy-=i1;i=mod289(i);vec3 p=permute(permute(i.y+vec3(0.0,i1.y,1.0))+i.x+vec3(0.0,i1.x,1.0));vec3 m=max(0.5-vec3(dot(x0,x0),dot(x12.xy,x12.xy),dot(x12.zw,x12.zw)),0.0);m=m*m;m=m*m;vec3 x=2.0*fract(p*C.www)-1.0;vec3 h=abs(x)-0.5;vec3 ox=floor(x+0.5);vec3 a0=x-ox;m*=1.79284291400159-0.85373472095314*(a0*a0+h*h);vec3 g;g.x=a0.x*x0.x+h.x*x0.y;g.yz=a0.yz*x12.xz+h.yz*x12.yw;return 130.0*dot(m,g);}void main(){vUv=uv;vec3 pos=position;float noise=snoise(vec2(pos.x*0.1,pos.y*0.1)+u_time*0.05);float noise2=snoise(vec2(pos.x*0.5,pos.y*0.5)+u_time*0.025);pos.z=(noise+noise2)*0.2;gl_Position=projectionMatrix*modelViewMatrix*vec4(pos,1.0);}`;
            const fragmentShader = `varying vec2 vUv;uniform float u_time;vec3 mod289(vec3 x){return x-floor(x*(1.0/289.0))*289.0;}vec2 mod289(vec2 x){return x-floor(x*(1.0/289.0))*289.0;}vec3 permute(vec3 x){return mod289(((x*34.0)+1.0)*x);}float snoise(vec2 v){const vec4 C=vec4(0.211324865405187,0.366025403784439,-0.577350269189626,0.024390243902439);vec2 i=floor(v+dot(v,C.yy));vec2 x0=v-i+dot(i,C.xx);vec2 i1;i1=(x0.x>x0.y)?vec2(1.0,0.0):vec2(0.0,1.0);vec4 x12=x0.xyxy+C.xxzz;x12.xy-=i1;i=mod289(i);vec3 p=permute(permute(i.y+vec3(0.0,i1.y,1.0))+i.x+vec3(0.0,i1.x,1.0));vec3 m=max(0.5-vec3(dot(x0,x0),dot(x12.xy,x12.xy),dot(x12.zw,x12.zw)),0.0);m=m*m;m=m*m;vec3 x=2.0*fract(p*C.www)-1.0;vec3 h=abs(x)-0.5;vec3 ox=floor(x+0.5);vec3 a0=x-ox;m*=1.79284291400159-0.85373472095314*(a0*a0+h*h);vec3 g;g.x=a0.x*x0.x+h.x*x0.y;g.yz=a0.yz*x12.xz+h.yz*x12.yw;return 130.0*dot(m,g);}void main(){vec3 color1=vec3(0.0,0.2,0.5);vec3 color2=vec3(0.0,0.48,1.0);vec3 specular=vec3(0.8,0.9,1.0);float noise=snoise(vUv*3.0+u_time*0.05);float mix_val=(noise+1.0)*0.5;vec3 final_color=mix(color1,color2,mix_val);float shine=smoothstep(0.7,0.8,noise);final_color=mix(final_color,specular,shine*0.5);gl_FragColor=vec4(final_color,1.0);}`;
            uniforms = {u_time: {value: 0.0}};
            const material = new THREE.ShaderMaterial({vertexShader, fragmentShader, uniforms, wireframe: false, side: THREE.DoubleSide});
            mesh = new THREE.Mesh(geometry, material);
            mesh.rotation.x = -Math.PI / 4.5;
            scene.add(mesh);
            camera.position.z = 3.5;
            animate3D();
        }
        function animate3D() {
            requestAnimationFrame(animate3D);
            uniforms.u_time.value = clock.getElapsedTime();
            renderer.render(scene, camera);
        }
        function onWindowResize() {
            camera.aspect = window.innerWidth / window.innerHeight;
            camera.updateProjectionMatrix();
            renderer.setSize(window.innerWidth, window.innerHeight);
        }
        window.addEventListener('resize', onWindowResize);
        init3DBackground();
        const API_BASE_URL = '';
        const chatView = document.getElementById('chat-view');
        const researchView = document.getElementById('research-view');
        const chatHistory = document.getElementById('chat-history');
        const messageForm = document.getElementById('message-form');
        const messageInput = document.getElementById('message-input');
        const sendButton = document.getElementById('send-button');
        const addButton = document.getElementById('add-button');
        const actionPopupMenu = document.getElementById('action-popup-menu');
        const menuResearch = document.getElementById('menu-research');
        const menuUpload = document.getElementById('menu-upload');
        const researchOptionsModalOverlay = document.getElementById('research-options-modal-overlay');
        const researchOptionsModal = document.getElementById('research-options-modal');
        const researchGoalSummary = document.getElementById('research-goal-summary');
        const submitResearchTask = document.getElementById('submit-research-task');
        const cancelResearchTask = document.getElementById('cancel-research-task');
        const toggleAdvancedOptions = document.getElementById('toggle-advanced-options');
        const advancedOptionsContainer = document.getElementById('advanced-options-container');
        const startDateInput = document.getElementById('start-date');
        const endDateInput = document.getElementById('end-date');
        const includeDomainsInput = document.getElementById('include-domains');
        const excludeDomainsInput = document.getElementById('exclude-domains');
        const researchBackButton = document.getElementById('research-back-button');
        const researchTitle = document.getElementById('research-title');
        const researchContent = document.getElementById('research-content');
        let researchTasks = {};
        let activeTaskId = null;
        let currentMode = 'chat';
        let pendingResearchGoal = '';
        let isPopupVisible = false;
        let uploadedFile = null;
        messageForm.addEventListener('submit', handleFormSubmit);
        messageInput.addEventListener('input', () => {
            sendButton.disabled = messageInput.value.trim().length === 0;
        });
        async function handleFormSubmit(e) {
            e.preventDefault();
            const prompt = messageInput.value.trim();
            if (!prompt) return;
            messageInput.value = '';
            sendButton.disabled = true;
            if (currentMode === 'chat') {
                sendChatMessage(prompt);
            } else {
                openResearchOptionsSheet(prompt);
            }
        }
        async function sendChatMessage(prompt) {
            addMessageToHistory(prompt, 'user');
            const typingId = addMessageToHistory(null, 'ai', 'typing-indicator');
            try {
                const response = await fetch(`${API_BASE_URL}/chat`, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({
                        messages: [{role: 'user', content: prompt}],
                        model: 'llama3.1-70b',
                        temperature: 0.7,
                        max_tokens: 120000
                    })
                });
                if (!response.ok) throw new Error(`API hiba: ${response.status}`);
                const result = await response.json();
                const aiResponse = result.choices?.[0]?.message?.content || 'Nincs válasz.';
                updateMessageInHistory(typingId, aiResponse, 'ai');
            } catch (error) {
                console.error('Hiba a Chat API hívásakor:', error);
                updateMessageInHistory(typingId, 'Hiba történt a válaszadás közben.', 'ai', true);
            }
        }
        function addMessageToHistory(text, type, customClass = '') {
            const messageId = 'msg-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);
            const messageDiv = document.createElement('div');
            messageDiv.className = `message ${type}`;
            messageDiv.id = messageId;
            if (customClass) messageDiv.classList.add(customClass);
            if (type === 'typing-indicator') {
                messageDiv.innerHTML = '<span class="typing-dot"></span><span class="typing-dot"></span><span class="typing-dot"></span>';
            } else {
                messageDiv.textContent = text;
            }
            chatHistory.appendChild(messageDiv);
            chatHistory.scrollTop = chatHistory.scrollHeight;
            return messageId;
        }
        function updateMessageInHistory(messageId, newText, type, isError = false) {
            const messageDiv = document.getElementById(messageId);
            if (!messageDiv) return;
            messageDiv.classList.remove('typing-indicator');
            messageDiv.className = `message ${type}`;
            if (isError) messageDiv.classList.add('error');
            messageDiv.textContent = newText;
            chatHistory.scrollTop = chatHistory.scrollHeight;
        }
        function setChatMode(mode) {
            currentMode = mode;
            if (currentMode === 'chat') {
                messageInput.className = 'mode-chat';
                sendButton.className = 'mode-chat';
                messageInput.placeholder = 'Üzenet...';
            } else {
                messageInput.className = 'mode-research';
                sendButton.className = 'mode-research';
                messageInput.placeholder = 'Adja meg a kutatás célját...';
            }
        }
        addButton.addEventListener('click', (e) => {
            e.stopPropagation();
            isPopupVisible = !isPopupVisible;
            actionPopupMenu.classList.toggle('visible', isPopupVisible);
        });
        document.addEventListener('click', () => {
            if (isPopupVisible) {
                isPopupVisible = false;
                actionPopupMenu.classList.remove('visible');
            }
        });
        menuResearch.addEventListener('click', (e) => {
            e.stopPropagation();
            setChatMode('research');
            isPopupVisible = false;
            actionPopupMenu.classList.remove('visible');
            messageInput.focus();
        });
        menuUpload.addEventListener('click', async (e) => {
            e.stopPropagation();
            isPopupVisible = false;
            actionPopupMenu.classList.remove('visible');
            const input = document.createElement('input');
            input.type = 'file';
            input.accept = '.txt,.md,.pdf,.doc,.docx';
            input.onchange = async (event) => {
                const file = event.target.files[0];
                if (file) {
                    uploadedFile = file;
                    addMessageToHistory(`Fájl feltöltve: ${file.name}`, 'ai');
                }
            };
            input.click();
        });
        function openResearchOptionsSheet(goal) {
            pendingResearchGoal = goal;
            researchGoalSummary.textContent = goal;
            researchOptionsModalOverlay.classList.add('visible');
        }
        cancelResearchTask.addEventListener('click', () => {
            researchOptionsModalOverlay.classList.remove('visible');
            pendingResearchGoal = '';
            setChatMode('chat');
        });
        toggleAdvancedOptions.addEventListener('click', () => {
            const isVisible = advancedOptionsContainer.style.display === 'block';
            advancedOptionsContainer.style.display = isVisible ? 'none' : 'block';
            toggleAdvancedOptions.textContent = isVisible ? 'Speciális Beállítások' : 'Beállítások Elrejtése';
        });
        submitResearchTask.addEventListener('click', async () => {
            researchOptionsModalOverlay.classList.remove('visible');
            const options = {
                max_sources: 100,
                start_published_date: startDateInput.value || null,
                end_published_date: endDateInput.value || null,
                include_domains: includeDomainsInput.value ? includeDomainsInput.value.split(',').map(d => d.trim()) : null,
                exclude_domains: excludeDomainsInput.value ? excludeDomainsInput.value.split(',').map(d => d.trim()) : null
            };
            addMessageToHistory(pendingResearchGoal, 'user');
            const widgetId = addResearchWidget(pendingResearchGoal, options);
            try {
                const formData = new FormData();
                formData.append('goal', pendingResearchGoal);
                formData.append('max_sources', options.max_sources);
                if (uploadedFile) {
                    formData.append('file', uploadedFile);
                }
                const response = await fetch(`${API_BASE_URL}/research/create`, {
                    method: 'POST',
                    body: formData
                });
                if (!response.ok) throw new Error(`API hiba: ${response.status}`);
                const result = await response.json();
                const taskId = result.task_id;
                researchTasks[taskId] = {widgetId, goal: pendingResearchGoal, options};
                updateResearchWidget(widgetId, taskId);
                pollResearchStatus(taskId);
            } catch (error) {
                console.error('Hiba a kutatás indításakor:', error);
                const widgetDiv = document.getElementById(widgetId);
                if (widgetDiv) {
                    widgetDiv.querySelector('.widget-status').textContent = 'Hiba történt';
                }
            }
            pendingResearchGoal = '';
            uploadedFile = null;
            setChatMode('chat');
        });
        function addResearchWidget(goal, options) {
            const widgetId = 'widget-' + Date.now() + '-' + Math.random().toString(36).substr(2, 9);
            const widgetDiv = document.createElement('div');
            widgetDiv.className = 'message widget';
            widgetDiv.id = widgetId;
            widgetDiv.innerHTML = `
                <div class="widget-header">
                    <svg xmlns="" viewBox="0 0 20 20" fill="currentColor">
                        <path fill-rule="evenodd" d="M11.29 2.234a.75.75 0 0 0-1.071 1.071 7.5 7.5 0 0 1 2.39 7.195.75.75 0 1 0 1.488-.287 9 9 0 0 0-2.86-8.622.75.75 0 0 0-.947-.357Z" clip-rule="evenodd"/>
                        <path fill-rule="evenodd" d="M8.71 2.234a.75.75 0 0 1 .947-.357 9 9 0 0 1 2.86 8.622.75.75 0 1 1-1.488-.287 7.5 7.5 0 0 0-2.39-7.195.75.75 0 0 1-.929-1.071l.001-.001.001-.001Z" clip-rule="evenodd"/>
                        <path fill-rule="evenodd" d="M10 18.25a8.25 8.25 0 1 0 0-16.5 8.25 8.25 0 0 0 0 16.5ZM10 3.25a6.75 6.75 0 1 0 0 13.5 6.75 6.75 0 0 0 0-13.5Z" clip-rule="evenodd"/>
                    </svg>
                    <h3>Kutatási Feladat</h3>
                </div>
                <div class="widget-body">
                    <div class="task-goal">${goal}</div>
                    <div class="task-params-summary">Max források: ${options.max_sources}</div>
                    <div class="widget-status">Indítás...</div>
                    <div class="widget-progress-bar">
                        <div class="widget-progress-inner" style="width: 0%;"></div>
                    </div>
                </div>
            `;
            widgetDiv.addEventListener('click', () => {
                const taskId = widgetDiv.dataset.taskId;
                if (taskId && researchTasks[taskId]) {
                    openResearchView(taskId);
                }
            });
            chatHistory.appendChild(widgetDiv);
            chatHistory.scrollTop = chatHistory.scrollHeight;
            return widgetId;
        }
        function updateResearchWidget(widgetId, taskId) {
            const widgetDiv = document.getElementById(widgetId);
            if (widgetDiv) {
                widgetDiv.dataset.taskId = taskId;
            }
        }
        async function pollResearchStatus(taskId) {
            const widgetId = researchTasks[taskId]?.widgetId;
            const pollInterval = setInterval(async () => {
                try {
                    const response = await fetch(`${API_BASE_URL}/research/${taskId}`);
                    if (!response.ok) throw new Error(`API hiba: ${response.status}`);
                    const data = await response.json();
                    const widgetDiv = document.getElementById(widgetId);
                    if (widgetDiv) {
                        const statusEl = widgetDiv.querySelector('.widget-status');
                        const progressBar = widgetDiv.querySelector('.widget-progress-inner');
                        statusEl.textContent = translateStatus(data.status);
                        progressBar.style.width = `${data.progress}%`;
                    }
                    if (data.status === 'completed' || data.status === 'error') {
                        clearInterval(pollInterval);
                        if (data.status === 'completed') {
                            researchTasks[taskId].report = data.report;
                            researchTasks[taskId].sources = data.sources;
                            researchTasks[taskId].sub_agents = data.sub_agents;
                        }
                    }
                } catch (error) {
                    console.error('Hiba a kutatási állapot lekérésénél:', error);
                    clearInterval(pollInterval);
                }
            }, 2000);
        }
        function translateStatus(status) {
            const statusMap = {
                'starting': 'Indítás...',
                'planning': 'Tervezés...',
                'searching': 'Keresés...',
                'analyzing': 'Elemzés...',
                'generating_report': 'Jelentés készítése...',
                'completed': 'Kész',
                'error': 'Hiba'
            };
            return statusMap[status] || status;
        }
        function openResearchView(taskId) {
            activeTaskId = taskId;
            const task = researchTasks[taskId];
            if (!task) return;
            chatView.classList.add('research-active');
            researchView.classList.add('visible');
            researchTitle.textContent = task.goal;
            researchContent.innerHTML = '';
            if (task.sub_agents && task.sub_agents.length > 0) {
                const agentSection = document.createElement('div');
                agentSection.innerHTML = '<div class="research-section-title">Ágensek</div>';
                const agentGrid = document.createElement('div');
                agentGrid.className = 'agent-grid';
                task.sub_agents.forEach(agent => {
                    const agentCard = document.createElement('div');
                    agentCard.className = 'agent-card';
                    agentCard.innerHTML = `
                        <svg class="agent-progress-donut" width="50" height="50" viewBox="0 0 50 50">
                            <circle class="donut-bg" cx="25" cy="25" r="20" fill="none" stroke="rgba(255,255,255,0.1)" stroke-width="4"></circle>
                            <circle class="donut-fg" cx="25" cy="25" r="20" fill="none" stroke="#007AFF" stroke-width="4" stroke-dasharray="${2 * Math.PI * 20}" stroke-dashoffset="${2 * Math.PI * 20 * (1 - agent.progress / 100)}" transform="rotate(-90 25 25)"></circle>
                            <text class="donut-text" x="25" y="25" text-anchor="middle" dominant-baseline="middle">${agent.progress}%</text>
                        </svg>
                        <div class="agent-card-info">
                            <div class="agent-card-title">${agent.name}</div>
                            <div class="agent-card-status">${agent.status}</div>
                        </div>
                    `;
                    agentGrid.appendChild(agentCard);
                });
                agentSection.appendChild(agentGrid);
                researchContent.appendChild(agentSection);
            }
            if (task.sources && task.sources.length > 0) {
                const sourcesSection = document.createElement('div');
                sourcesSection.innerHTML = '<div class="research-section-title">Források</div>';
                task.sources.forEach(source => {
                    const sourceItem = document.createElement('div');
                    sourceItem.className = 'similar-link-item';
                    sourceItem.innerHTML = `
                        <div class="icon-placeholder">
                            <svg xmlns="" viewBox="0 0 20 20" fill="currentColor">
                                <path fill-rule="evenodd" d="M4.25 5.5a.75.75 0 0 0-.75.75v8.5c0 .414.336.75.75.75h8.5a.75.75 0 0 0 .75-.75v-4a.75.75 0 0 1 1.5 0v4A2.25 2.25 0 0 1 12.75 17h-8.5A2.25 2.25 0 0 1 2 14.75v-8.5A2.25 2.25 0 0 1 4.25 4h5a.75.75 0 0 1 0 1.5h-5Z" clip-rule="evenodd"/>
                                <path fill-rule="evenodd" d="M6.194 12.753a.75.75 0 0 0 1.06.053L16.5 4.44v2.81a.75.75 0 0 0 1.5 0v-4.5a.75.75 0 0 0-.75-.75h-4.5a.75.75 0 0 0 0 1.5h2.553l-9.056 8.194a.75.75 0 0 0-.053 1.06Z" clip-rule="evenodd"/>
                            </svg>
                        </div>
                        <div class="item-text">
                            <div class="item-title">${source.title || 'Untitled'}</div>
                            <div class="item-url">${source.url || ''}</div>
                        </div>
                    `;
                    sourcesSection.appendChild(sourceItem);
                });
                researchContent.appendChild(sourcesSection);
            }
            if (task.report) {
                const reportSection = document.createElement('div');
                reportSection.innerHTML = '<div class="research-section-title">Jelentés</div>';
                const reportDiv = document.createElement('div');
                reportDiv.style.cssText = 'background: var(--ai-bubble-bg); border: 1px solid var(--widget-border); border-radius: 12px; padding: 20px; line-height: 1.6;';
                reportDiv.textContent = task.report;
                reportSection.appendChild(reportDiv);
                researchContent.appendChild(reportSection);
            }
        }
        researchBackButton.addEventListener('click', () => {
            chatView.classList.remove('research-active');
            researchView.classList.remove('visible');
            activeTaskId = null;
        });
    </script>
</body>
</html>
